import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        Scanner in = new Scanner(System.in);
        int n = Integer.parseInt(in.nextLine());
        try (PrintWriter w = new PrintWriter(new FileWriter("belanja.txt"))) {
            for (int i = 0; i < n; i++) {
                w.println(in.nextLine());
            }
        }
        System.out.println("Tersimpan: " + n + " barang");
        System.out.println("Ukuran: " + new File("belanja.txt").length() + " byte");
    }
}
